using System;
using System.IO;
using System.Linq;
namespace LoopPedal {
static class TriggerChecks {
 public static void Run(){try{
 using(var e=new Engine()){e.WaitForInput=true;e.TriggerDb=-40;var input=new Input(new SourceChoice{Name="Live",Left=0,Right=1});e.Inputs.Add(input);e.Begin(false);var quiet=Enumerable.Repeat(.001f,256).ToArray();input.Feed(quiet,quiet.Length,2,e.AudioFrame);e.Mix(new float[256],128);if(!e.WaitingForInput||e.CapturedFrames!=0||e.CountInAudible)throw new Exception("Quiet input triggered");var signal=new float[1024];for(int i=300;i<512;i++)signal[i*2]=signal[i*2+1]=.2f;input.Feed(signal,signal.Length,2,e.AudioFrame);if(e.WaitingForInput||e.RecordStartAudio!=428||e.CapturedFrames!=212)throw new Exception("In-buffer trigger alignment");e.Mix(new float[1024],512);input.Feed(Enumerable.Repeat(.2f,960).ToArray(),960,2,e.AudioFrame);e.Finish(false);var l=e.Layers.Single();if(l.Offset!=428||l.Original.Length!=1384||l.Original.Any(v=>v!=.2f))throw new Exception("Trigger lost onset or changed gain");}
 using(var e=new Engine()){e.WaitForInput=e.AutoOverdub=e.Sync=true;e.BPM=300;var input=new Input(new SourceChoice{Name="Live",Left=0,Right=1});e.Inputs.Add(input);e.Begin(false);int period=Engine.MeasureFrames(300,4,4,1);var signal=new float[(period*2+10)*2];for(int i=10;i<signal.Length/2;i++)signal[i*2]=signal[i*2+1]=.15f;input.Feed(signal,signal.Length,2,0);e.DrainCompletedPasses();if(e.Layers.Count!=2||e.Layers[0].Offset!=10||e.Layers[1].Offset!=10+period||e.WaitingForInput||!e.Recording)throw new Exception("Auto overdub rearmed or shifted");e.Finish(false);}
 using(var a=new Engine())using(var b=new Engine()){a.LoopFrames=1000;a.Frame=700;a.AudioFrame=5000;b.AudioFrame=5000;b.Frame=200;b.QuantizePeer=a;b.StartQuantize=2;b.WaitForInput=true;var input=new Input(new SourceChoice{Name="Live",Left=0,Right=1});b.Inputs.Add(input);b.Begin(false);var signal=new float[1000];signal[800]=signal[801]=.2f;input.Feed(signal,signal.Length,2,5000);if(b.RecordStartAudio!=6300||b.CapturedFrames!=0)throw new Exception("Quantized trigger scheduled before detected onset");b.Finish(false);}
 using(var e=new Engine()){e.WaitForInput=e.AutoOverdub=true;e.LoopFrames=1200;e.Layers.Add(new Layer{Name="Existing",Audio=new float[2400],Original=new float[2400]});e.Inputs.Add(new Input(new SourceChoice{Name="Live",Left=0,Right=1}));e.Begin(false);e.Finish();if(e.Recording||e.Layers.Count!=1)throw new Exception("Cancel created a layer or auto rearmed");}
 using(var e=new Engine()){e.WaitForInput=true;e.CountInBars=1;e.Inputs.Add(new Input(new SourceChoice{Name="Live",Left=0,Right=1}));e.Begin(false);e.ObserveInput(.2f,.2f,321);if(e.RecordStartAudio!=321+Engine.MeasureFrames(120,4,4,1))throw new Exception("Count-in did not begin after trigger");e.Finish(false);}
 File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"input-trigger-tests.txt"),"PASS: quiet input ignored; exact onset within a buffer; unity samples; quantization after onset; count-in after trigger; continuous automatic overdub; cancelling armed take creates no layer.");
 }catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"input-trigger-tests.txt"),"FAIL: "+e);Environment.ExitCode=1;}}
}}
